/// Sample `track` (a pose for any time) inside the shutter interval centred on `t`.
/// The sample count scales with on-screen travel: 1 at rest, so a resting node costs nothing
/// extra (`is_moving()` is false and the caller draws the node normally).
#[napi(js_name = "__R_fx_MotionSamples_from_track", skip_typescript)]
pub fn __r_fx_motionsamples_from_track(a_p: Raw, a_rest: Raw, a_t: Raw, a_scale: Raw, a_track: Raw) -> napi::Result<Raw> {
    conv::guard(|| {
        let a_p: rune_fx::MotionBlurParams = conv::arg(a_p.0, "p")?;
        let a_rest: rune_motion::Rect = conv::arg(a_rest.0, "rest")?;
        let a_t: f32 = conv::arg(a_t.0, "t")?;
        let a_scale: f32 = conv::arg(a_scale.0, "scale")?;
        let a_track_h = conv::arg::<conv::JsFn>(a_track.0, "track")?.0;
        let a_track = move |c0: f32| -> rune_fx::Pose { crate::js::scope(|| { { let v0 = conv::arg_js(c0); let r = a_track_h.call(&[v0]); conv::ret_or(r, Default::default) } }) };
        
        let out = conv::ToJs::to_js(rune_fx::MotionSamples::from_track(&a_p, a_rest, a_t, a_scale, a_track))?;
        Ok(Raw(out))
    })
}

