impl FromJs for rune_fx::PulseStyle {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "PulseStyle")?;
        match (tag.as_str(), payload) {
            ("Radar", _) => Ok(rune_fx::PulseStyle::Radar),
            ("Breathe", _) => Ok(rune_fx::PulseStyle::Breathe),
            ("Heartbeat", _) => Ok(rune_fx::PulseStyle::Heartbeat),
            ("Ping", Some(p)) => Ok(rune_fx::PulseStyle::Ping { from: conv::field::<[f32; 2]>(p, "PulseStyle.Ping", "from")?, dir: conv::field::<[f32; 2]>(p, "PulseStyle.Ping", "dir")?, travel: conv::field::<f32>(p, "PulseStyle.Ping", "travel")? }),
            ("Ripple", Some(p)) => Ok(rune_fx::PulseStyle::Ripple { at: conv::field::<[f32; 2]>(p, "PulseStyle.Ripple", "at")? }),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "PulseStyle"))),
        }
    }
}
impl ToJs for rune_fx::PulseStyle {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune_fx::PulseStyle::Radar => conv::ToJs::to_js("Radar"),
            rune_fx::PulseStyle::Breathe => conv::ToJs::to_js("Breathe"),
            rune_fx::PulseStyle::Heartbeat => conv::ToJs::to_js("Heartbeat"),
            rune_fx::PulseStyle::Ping { from, dir, travel } => { let o = conv::object(); conv::set(o, "from", from.to_js()?); conv::set(o, "dir", dir.to_js()?); conv::set(o, "travel", travel.to_js()?); Ok(conv::tagged("Ping", o)) }
            rune_fx::PulseStyle::Ripple { at } => { let o = conv::object(); conv::set(o, "at", at.to_js()?); Ok(conv::tagged("Ripple", o)) }
            _ => Ok(conv::undefined()),
        }
    }
}

