impl FromJs for rune_fx::Fx {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "Fx")?;
        match (tag.as_str(), payload) {
            ("Glow", Some(p)) => Ok(rune_fx::Fx::Glow(conv::arg::<rune_fx::GlowParams>(p, "Fx.Glow")?)),
            ("Pulse", Some(p)) => Ok(rune_fx::Fx::Pulse(conv::arg::<rune_fx::PulseParams>(p, "Fx.Pulse")?)),
            ("Electric", Some(p)) => Ok(rune_fx::Fx::Electric(conv::arg::<rune_fx::ElectricParams>(p, "Fx.Electric")?)),
            ("Fire", Some(p)) => Ok(rune_fx::Fx::Fire(conv::arg::<rune_fx::FireParams>(p, "Fx.Fire")?)),
            ("Distort", Some(p)) => Ok(rune_fx::Fx::Distort(conv::arg::<rune_fx::DistortParams>(p, "Fx.Distort")?)),
            ("MotionBlur", Some(p)) => Ok(rune_fx::Fx::MotionBlur(conv::arg::<rune_fx::MotionBlurParams>(conv::element_at(p, 0), "Fx.MotionBlur[0]")?, conv::arg::<rune_fx::MotionSamples>(conv::element_at(p, 1), "Fx.MotionBlur[1]")?)),
            ("Shimmer", Some(p)) => Ok(rune_fx::Fx::Shimmer(conv::arg::<rune_fx::ShimmerParams>(p, "Fx.Shimmer")?)),
            ("Sparkles", Some(p)) => Ok(rune_fx::Fx::Sparkles(conv::arg::<rune_fx::SparkleParams>(p, "Fx.Sparkles")?)),
            ("Aurora", Some(p)) => Ok(rune_fx::Fx::Aurora(conv::arg::<rune_fx::AuroraParams>(p, "Fx.Aurora")?)),
            ("Grain", Some(p)) => Ok(rune_fx::Fx::Grain(conv::arg::<rune_fx::GrainParams>(p, "Fx.Grain")?)),
            ("Fill", Some(p)) => Ok(rune_fx::Fx::Fill(conv::arg::<rune_fx::FillParams>(p, "Fx.Fill")?)),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "Fx"))),
        }
    }
}
impl ToJs for rune_fx::Fx {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune_fx::Fx::Glow(a) => Ok(conv::tagged("Glow", a.to_js()?)),
            rune_fx::Fx::Pulse(a) => Ok(conv::tagged("Pulse", a.to_js()?)),
            rune_fx::Fx::Electric(a) => Ok(conv::tagged("Electric", a.to_js()?)),
            rune_fx::Fx::Fire(a) => Ok(conv::tagged("Fire", a.to_js()?)),
            rune_fx::Fx::Distort(a) => Ok(conv::tagged("Distort", a.to_js()?)),
            rune_fx::Fx::MotionBlur(a0, a1) => Ok(conv::tagged("MotionBlur", conv::array([a0.to_js()?, a1.to_js()?]))),
            rune_fx::Fx::Shimmer(a) => Ok(conv::tagged("Shimmer", a.to_js()?)),
            rune_fx::Fx::Sparkles(a) => Ok(conv::tagged("Sparkles", a.to_js()?)),
            rune_fx::Fx::Aurora(a) => Ok(conv::tagged("Aurora", a.to_js()?)),
            rune_fx::Fx::Grain(a) => Ok(conv::tagged("Grain", a.to_js()?)),
            rune_fx::Fx::Fill(a) => Ok(conv::tagged("Fill", a.to_js()?)),
            _ => Ok(conv::undefined()),
        }
    }
}

